"""Migrated Meridian CRM 4.2 order_fulfilment workflow."""

from typing import Any


def _numeric(value: Any) -> float:
    """Apply legacy numeric coercion: missing/empty values compare as zero."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _account_credit_hold(record: dict, tables: dict) -> Any:
    """Implement legacy LOOKUP first-live-row behavior for ACCT_MASTER."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") != "Y" and row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire one order_fulfilment workflow event using legacy transition semantics."""
    result_record = dict(record)

    # Document-order transition 1: E -> A, approve.
    if (
        state == "E"
        and event == "approve"
        and _numeric(record.get("TOT_AMT", "")) > 0
    ):
        return {
            "state": "A",
            "record": result_record,
            "audits": ["ORD_APPR"],
            "notifies": [],
            "matched": True,
        }

    # Document-order transition 2: A -> S, ship.
    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": result_record,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    # Document-order transition 3: S -> I, invoice.
    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": result_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    # Document-order transition 4: E -> X, cancel.
    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    # Document-order transition 5: A -> X, cancel.
    if (
        state == "A"
        and event == "cancel"
        and _account_credit_hold(record, tables) != "Y"
    ):
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    # Document-order transition 6: I -> X, cancel.
    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
